def f(N: int, edges: List[Tuple[int, int]]): 
    ''' 
    N: an integer 
    edges: a list of tuples, each containing two integers
    ''' 
    graph = [[] for _ in range(N+1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    visited = [False] * (N+1)
    cycle = -1
    def dfs(v):
        nonlocal cycle
        visited[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                dfs(neighbor)
            else:
                if neighbor!= cycle:
                    cycle = v
    for V in range(1, N+1):
        if not visited[V]:
            dfs(V)
    return cycle
